#!/usr/bin/env python3
"""
cleanup_logs.py

Finds and removes all .bash_history files within /home and /root directories.
Uses os.walk to traverse directories and os.remove to delete matching files.
"""

import os


TARGET_FILENAME = ".bash_history"
SEARCH_ROOTS = ["/home", "/root"]


def remove_bash_history_files(roots):
    """Walk each root directory and remove any .bash_history files found."""
    removed = []
    errors = []

    for root in roots:
        if not os.path.exists(root):
            print(f"Skipping {root!r}: path does not exist.")
            continue

        for dirpath, dirnames, filenames in os.walk(root):
            if TARGET_FILENAME in filenames:
                file_path = os.path.join(dirpath, TARGET_FILENAME)
                try:
                    os.remove(file_path)
                    removed.append(file_path)
                    print(f"Removed: {file_path}")
                except OSError as exc:
                    errors.append((file_path, str(exc)))
                    print(f"Error removing {file_path}: {exc}")

    return removed, errors


def main():
    removed, errors = remove_bash_history_files(SEARCH_ROOTS)
    print(f"\nDone. {len(removed)} file(s) removed, {len(errors)} error(s).")


if __name__ == "__main__":
    main()
